    /**
     * Method to retrieve the Screening via ScreeningFetchOneSummary
     * @param 	summary ScreeningFetchOneSummary 
     * @return 	ScreeningFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Screening getScreening( ScreeningFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "ScreeningFetchOneSummary arg cannot be null" );
    	
    	Screening entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Screening
        	// --------------------------------------
        	CompletableFuture<Screening> futureEntity = queryGateway.query(new FindScreeningQuery( new LoadScreeningFilter( summary.getScreeningId() ) ), ResponseTypes.instanceOf(Screening.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Screening with id " + summary.getScreeningId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


